private isSafeExternalUrl(url: string): boolean {
  return /^https?:\/\//i.test(url) && !/^javascript:/i.test(url);
}

navigateTo(cta: HeroCta): void {
  if (cta.href && this.isBrowser && this.isSafeExternalUrl(cta.href)) {
    window.open(cta.href, '_blank', 'noopener,noreferrer');
  } else if (cta.routerLink) {
    this.router.navigate([cta.routerLink], { fragment: cta.fragment, onSameUrlNavigation: 'reload' });
  }
}

