1	import { Component, AfterViewInit, OnDestroy, ElementRef, ViewChild, PLATFORM_ID, Inject, NgZone } from '@angular/core';
2	import { isPlatformBrowser } from '@angular/common';
3	import type * as Leaflet from 'leaflet';
4	import type { Feature, GeoJsonProperties, Geometry } from 'geojson';
5	import { FV_MAP } from '../../../core/data/map.data';
6	import { MapPoint } from '../../../core/models/map.model';
7	
8	const ACTIVE_COUNTRIES = [
9	  'Senegal','Côte d\'Ivoire','Ghana','Nigeria','Cameroon',
10	  'Ethiopia','Uganda','Rwanda','Kenya','Tanzania',
11	  'Zambia','Malawi','Mozambique','South Africa','Madagascar','Mali','Burkina Faso'
12	];
13	
14	const TYPE_COLORS: Record<MapPoint['type'], string> = {
15	  forestry: '#2D6A4F',
16	  energy:   '#D4870A',
17	  agri:     '#5C7259',
18	  waste:    '#4A4A5A',
19	};
20	
21	@Component({
22	    selector: 'fv-map-section',
23	    imports: [],
24	    templateUrl: './map-section.component.html',
25	    styleUrl: './map-section.component.scss'
26	})
27	export class MapSectionComponent implements AfterViewInit, OnDestroy {
28	  @ViewChild('mapEl', { static: true }) mapEl!: ElementRef<HTMLDivElement>;
29	
30	  private map?: Leaflet.Map;
31	  private L?: typeof Leaflet;
32	  private resizeObserver?: ResizeObserver;
33	
34	  constructor(
35	    @Inject(PLATFORM_ID) private platformId: object,
36	    private zone: NgZone,
37	  ) {}
38	
39	  async ngAfterViewInit(): Promise<void> {
40	    if (!isPlatformBrowser(this.platformId)) return;
41	
42	    const L = await import('leaflet');
43	    this.L = L;
44	
45	    this.zone.runOutsideAngular(() => {
46	      this.map = L.map(this.mapEl.nativeElement, {
47	        center: [2, 22],
48	        zoom: 3,
49	        zoomControl: false,
50	        attributionControl: false,
51	        scrollWheelZoom: false,
52	        dragging: false,
53	        doubleClickZoom: false,
54	        touchZoom: false,
55	      });
56	
57	      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_nolabels/{z}/{x}/{y}{r}.png', {
58	        subdomains: 'abcd',
59	        maxZoom: 6,
60	      }).addTo(this.map);
61	
62	      // Recalculate size once the browser has painted the container
63	      setTimeout(() => this.map?.invalidateSize(), 0);
64	
65	      // Keep map correct if the container resizes (e.g. sidebar open/close)
66	      this.resizeObserver = new ResizeObserver(() => this.map?.invalidateSize());
67	      this.resizeObserver.observe(this.mapEl.nativeElement);
68	    });
69	
70	    await this.addCountryLayer();
71	    this.addProjectMarkers(L);
72	  }
73	
74	  private async addCountryLayer(): Promise<void> {
75	    try {
76	      const res = await fetch('https://raw.githubusercontent.com/datasets/geo-countries/master/data/countries.geojson');
77	      const geoJson = await res.json();
78	
79	      const L = this.L;
80	      if (!L || !this.map) return;
81	      L.geoJSON(geoJson, {
82	        filter: (feature: Feature<Geometry, GeoJsonProperties>) =>
83	          !!feature.properties && ACTIVE_COUNTRIES.includes(feature.properties['ADMIN']),
84	        style: () => ({
85	          fillColor: '#F5A623',
86	          fillOpacity: 0.35,
87	          color: '#D4870A',
88	          weight: 1.2,
89	        }),
90	      }).addTo(this.map);
91	    } catch {
92	      // silently skip country highlight if fetch fails
93	    }
94	  }
95	
96	  private addProjectMarkers(L: typeof Leaflet): void {
97	    if (!this.map) return;
98	    for (const point of FV_MAP) {
99	      const color = TYPE_COLORS[point.type] ?? '#2D6A4F';
100	      const icon = L.divIcon({
101	        className: '',
102	        html: `<div style="
103	          width:10px;height:10px;border-radius:50%;
104	          background:${color};border:2px solid #fff;
105	          box-shadow:0 1px 4px rgba(0,0,0,0.35);
106	          cursor:pointer;
107	        "></div>`,
108	        iconSize: [10, 10],
109	        iconAnchor: [5, 5],
110	      });
111	
112	      L.marker([point.lat, point.lng], { icon })
113	        .addTo(this.map)
114	        .bindPopup(`<strong>${point.name}</strong><br><span style="color:#666;font-size:12px">${point.country}</span>`, {
115	          closeButton: false,
116	          className: 'fv-popup',
117	        });
118	    }
119	  }
120	
121	  ngOnDestroy(): void {
122	    this.resizeObserver?.disconnect();
123	    this.map?.remove();
124	  }
125	}

